const baseNews=[
{cat:"LEVEL AR",title:"أخبار الألعاب أولاً بأول",text:"تابع آخر أخبار الألعاب والتحديثات والإعلانات المهمة داخل LEVEL AR."},
{cat:"Gaming",title:"دليل الألعاب",text:"معلومات مختصرة عن أشهر الألعاب والمنصات والأنواع المختلفة."},
{cat:"PC",title:"ألعاب الكمبيوتر",text:"أبرز ألعاب الكمبيوتر التي تستحق المتابعة."},
{cat:"PlayStation",title:"أخبار PlayStation",text:"متابعة لأهم الإصدارات والتحديثات والألعاب المنتظرة."},
{cat:"Xbox",title:"أخبار Xbox",text:"أحدث المستجدات الخاصة بألعاب Xbox والكمبيوتر."},
{cat:"Nintendo",title:"أخبار Nintendo",text:"أبرز ألعاب Nintendo والمشاريع المنتظرة."}
];

function gameCard(g){return `<article class="card game-card" data-game="${encodeURIComponent(g.title)}" tabindex="0" role="button"><img loading="lazy" src="${g.image}" alt="${escapeHtml(g.title)}"><div class="info"><span class="tag">${escapeHtml(g.genre)}</span><h3>${escapeHtml(g.title)}</h3><span class="muted">${escapeHtml(g.platforms||g.developer)}</span><small class="muted">📰 10 أخبار لهذه اللعبة</small></div></article>`}
function newsCard(n){return `<article class="news"><span class="tag">${escapeHtml(n.cat||"Gaming")}</span><h3>${escapeHtml(n.title)}</h3><p>${escapeHtml(n.text)}</p>${n.game?`<small class="muted">🎮 ${escapeHtml(n.game)}</small>`:""}</article>`}
function escapeHtml(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));}
async function load(){
 if(DATA)return DATA;
 try{DATA=await fetch("assets/data.json").then(r=>r.json())}catch(e){DATA={games:[],videos:[],companies:[]}}
 const seen=new Set((DATA.games||[]).map(g=>String(g.title).toLowerCase()));
 LEVELAR_GAMES.forEach(g=>{if(!seen.has(g.title.toLowerCase()))DATA.games.push(g)});
 return DATA;
}
function allGameNews(){return LEVELAR_GAMES.flatMap(g=>g.news.map(n=>({...n,game:g.title})))}
function addModal(){if($("#levelarGameModal"))return;document.body.insertAdjacentHTML("beforeend",`<div id="levelarGameModal" class="levelar-modal" aria-hidden="true"><div class="levelar-modal-box"><button class="levelar-close" aria-label="إغلاق">×</button><div id="levelarModalBody"></div></div></div>`);
 $(".levelar-close").onclick=closeModal;$("#levelarGameModal").addEventListener("click",e=>{if(e.target.id==="levelarGameModal")closeModal()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});}
function openGame(title){const g=LEVELAR_GAMES.find(x=>x.title===title);if(!g)return;addModal();$("#levelarModalBody").innerHTML=`<img class="levelar-modal-cover" src="${g.image}" alt=""><span class="tag">${escapeHtml(g.genre)}</span><h2>${escapeHtml(g.title)}</h2><p class="muted">${escapeHtml(g.platforms)} — ${escapeHtml(g.developer)}</p><h3>📰 أخبار اللعبة</h3><div class="levelar-news-list">${g.news.map(newsCard).join("")}</div>`;$("#levelarGameModal").classList.add("show");$("#levelarGameModal").setAttribute("aria-hidden","false");}
function closeModal(){const m=$("#levelarGameModal");if(m){m.classList.remove("show");m.setAttribute("aria-hidden","true")}}
function wireCards(){document.querySelectorAll(".game-card").forEach(c=>{c.onclick=()=>openGame(decodeURIComponent(c.dataset.game));c.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openGame(decodeURIComponent(c.dataset.game))}}})}

function render(){
 const d=DATA; let e;
 e=$("#homeGames");if(e){e.innerHTML=d.games.slice(0,8).map(gameCard).join("");wireCards()}
 e=$("#gamesGrid");if(e){const renderGames=()=>{let q=($("#gameSearch")?.value||"").toLowerCase().trim();let list=d.games.filter(g=>(g.title+" "+g.developer+" "+g.genre+" "+(g.platforms||"")).toLowerCase().includes(q));e.innerHTML=list.map(gameCard).join("");wireCards();};renderGames();$("#gameSearch")?.addEventListener("input",renderGames)}
 const n=allGameNews();
 e=$("#homeNews");if(e)e.innerHTML=[...n,...baseNews].slice(0,6).map(newsCard).join("");
 e=$("#newsGrid");if(e){e.innerHTML=n.map(newsCard).join("");}
 e=$("#companyGrid");if(e)e.innerHTML=(d.companies||[]).map(c=>`<article class="company"><img loading="lazy" src="${c.image}" alt="${escapeHtml(c.name)}"><h3>${escapeHtml(c.name)}</h3><span class="muted">${escapeHtml(c.parent)}</span></article>`).join("");
 e=$("#videoGrid");if(e)e.innerHTML=(d.videos||[]).map((v,i)=>videoCard(v,i)).join("");
 addModal();
}
function videoCard(v,i){const src=v.id?`https://www.youtube-nocookie.com/embed/${encodeURIComponent(v.id)}?rel=0&modestbranding=1&playsinline=1`:`https://www.youtube.com/embed?listType=search&list=${encodeURIComponent(v.channel||"gaming")}`;return `<article class="video"><div class="thumb"><iframe loading="lazy" src="${src}" title="${escapeHtml(v.title)}" allow="accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture;web-share" allowfullscreen></iframe></div><div class="vinfo"><b>${escapeHtml(v.title)}</b><div class="tag">${escapeHtml(v.channel)}</div></div></article>`}

(function injectStyle(){const s=document.createElement("style");s.textContent=`.game-card{cursor:pointer;transition:.2s}.game-card:hover{transform:translateY(-4px)}.game-card small{display:block;margin-top:8px}.levelar-modal{position:fixed;inset:0;background:rgba(0,0,0,.78);z-index:9999;display:none;padding:18px;overflow:auto}.levelar-modal.show{display:block}.levelar-modal-box{max-width:850px;margin:5vh auto;background:#111;color:#fff;border-radius:18px;padding:22px;position:relative}.levelar-close{position:absolute;left:15px;top:10px;width:42px;height:42px;border:0;border-radius:50%;font-size:30px;cursor:pointer}.levelar-modal-cover{width:150px;height:200px;object-fit:cover;border-radius:12px;float:right;margin:0 0 15px 18px}.levelar-news-list{display:grid;gap:10px;clear:both}.levelar-news-list .news{background:rgba(255,255,255,.06);padding:14px;border-radius:12px}.levelar-news-list h3{margin:7px 0}.levelar-news-list p{margin:0 0 7px}.levelar-modal-box:after{content:"";display:block;clear:both}@media(max-width:600px){.levelar-modal{padding:8px}.levelar-modal-box{margin:2vh auto;padding:16px}.levelar-modal-cover{width:100px;height:140px}}`;document.head.appendChild(s)})();

